# Simulating a graph node structure (like networkx)
class Graph:
    def __init__(self):
        self.adj_list = {}

    def add_edge(self, u, v):
        self.adj_list.setdefault(u, []).append(v)
        self.adj_list.setdefault(v, []).append(u)

    def neighbors(self, node):
        return self.adj_list.get(node, [])

g = Graph()
g.add_edge("ServerA", "ServerB")
g.add_edge("ServerB", "Database")
print("ServerB connections:", g.neighbors("ServerB"))

